<article class="product-card" data-stream-key="product-<?= (int)$_productCard['id'] ?>"><div class="product-image"><a href="<?= e($productUrl) ?>" aria-label="View <?= e($_productCard['name']) ?>"><?php if($imageUrl): ?><img src="<?= e($imageUrl) ?>" alt="<?= e($_productCard['name']) ?>" width="1200" height="1500" loading="lazy" decoding="async"><?php else:$visualCategory=$_productCard['category_name']??'';$placeholderLarge=false;require __DIR__.'/product_placeholder.php';endif; ?></a>
